"""
Security Threat Alert Definitions & Serialization
=================================================
Defines standardized alert data structures, severity tiers, and remediation recommendations.
"""

from dataclasses import dataclass, field
from datetime import datetime
from typing import Dict, Any
import uuid


class Severity:
    LOW = "LOW"
    MEDIUM = "MEDIUM"
    HIGH = "HIGH"
    CRITICAL = "CRITICAL"


@dataclass
class ThreatAlert:
    """Security threat alert generated by the anomaly detection engine."""
    rule_name: str
    severity: str
    source: str
    target: str
    description: str
    recommendation: str
    evidence: Dict[str, Any] = field(default_factory=dict)
    alert_id: str = field(default_factory=lambda: str(uuid.uuid4())[:8])
    timestamp: float = field(default_factory=lambda: datetime.now().timestamp())

    @property
    def formatted_time(self) -> str:
        """Return human-readable timestamp."""
        return datetime.fromtimestamp(self.timestamp).strftime("%H:%M:%S")

    def to_dict(self) -> Dict[str, Any]:
        """Convert alert to serializable dictionary."""
        return {
            "alert_id": self.alert_id,
            "timestamp": self.timestamp,
            "formatted_time": self.formatted_time,
            "rule_name": self.rule_name,
            "severity": self.severity,
            "source": self.source,
            "target": self.target,
            "description": self.description,
            "recommendation": self.recommendation,
            "evidence": self.evidence
        }
